      int remove = s2.charAt(i - 1);
      int add = s2.charAt(i - 1 + len);

      if (count[remove]++ >= 0) {
        total++;
      }

      if (count[add]-- > 0) {
        total--;
      }

      if (total == 0) {
        return i;
      }
    }
    return -1;
